def abort(message):
    sys.stderr.write('CONFLICTO: '+message+'\n')
    sys.exit(2)
if len(sys.argv) < 2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/ruta/public_html bash script --check|--apply|--restore [respaldo]\n')
    sys.exit(1)
mode=sys.argv[1]
root_text=os.environ.get('IMPE_CRM_PUBLIC','')
if not root_text: abort('Define IMPE_CRM_PUBLIC con la ruta completa del CRM.')
root=Path(root_text).resolve()
if not (root/'index.php').is_file(): abort('La ruta no parece la raíz del CRM.')
backup_root=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-ventas-resultados-backups'))).resolve()
if root==backup_root or root in backup_root.parents: abort('Los respaldos deben quedar fuera del sitio web.')
if backup_root==root or backup_root in root.parents: abort('No se permiten respaldos sobre directorios superiores al sitio.')
def digest(data): return hashlib.sha256(data).hexdigest()
def normalized(data): return data.replace(b'\r\n',b'\n')
def file_for(rel):
    p=root/rel
    if p.is_symlink() or not p.is_file() or root not in p.resolve().parents: abort('Archivo ausente o enlace no permitido: '+rel)
    return p
def atomic(path,data,mode):
    fd,name=tempfile.mkstemp(prefix='.impe-',dir=str(path.parent))
    try:
        os.fchmod(fd,mode)
        with os.fdopen(fd,'wb') as fh:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(name,str(path))
    finally:
        if os.path.exists(name): os.unlink(name)
if mode=='--restore':
    if len(sys.argv)!=3: abort('Indica el directorio privado del respaldo.')
    backup=Path(sys.argv[2]).resolve()
    if backup_root not in backup.parents or backup.is_symlink(): abort('Respaldo fuera del directorio privado.')
    manifest_path=backup/'manifest.json'
    if not manifest_path.is_file(): abort('Manifiesto de respaldo ausente.')
    entries=json.loads(manifest_path.read_text(encoding='utf-8'))
    prepared=[]
    for row in entries:
        if row.get('path') not in [x['path'] for x in SPECS]: abort('Ruta no admitida en el respaldo.')
        p=file_for(row['path'])
        data=p.read_bytes()
        prior=(backup/row['backup']).read_bytes()
        if digest(prior)!=row['original_sha256']: abort('Respaldo corrupto: '+row['path'])
        if digest(data) not in (row['applied_sha256'],row['original_sha256']):
            abort('El sitio cambió después de aplicar: '+row['path'])
        prepared.append((p,prior,row['mode'],digest(data)==row['applied_sha256']))
    for p,data,permission,needed in prepared:
        if needed: atomic(p,data,permission)
    print('OK: restauración exacta verificada. No se tocó la BD.')
    sys.exit(0)
actions=[]
for item in SPECS:
    p=file_for(item['path'])
    current=p.read_bytes()
    eol=b'\r\n' if b'\r\n' in current else b'\n'
    old=item['before'].encode('utf-8')
    new=item['after'].encode('utf-8')
    if normalized(current)==normalized(new):
        kind='actualizado'
    elif normalized(current)==normalized(old):
        kind='pendiente'
    else:
        abort('Variante desconocida; no se sobrescribe: '+item['path'])
    target=new.replace(b'\n',eol)
    actions.append(dict(path=item['path'],file=p,current=current,target=target,
                        permission=stat.S_IMODE(p.stat().st_mode),kind=kind))
for item in actions: print(item['path']+': '+item['kind'])
count=len([x for x in actions if x['kind']=='pendiente'])
print('Archivos a modificar:',count)
if mode=='--check':
    print('OK: comprobación de solo lectura. No se aplicaron cambios.')
    sys.exit(0)
if len(sys.argv)!=2: abort('Parámetros adicionales no admitidos en apply.')
if count==0:
    print('OK: archivos ya actualizados. No se realizaron cambios.')
    sys.exit(0)
backup_root.mkdir(mode=0o700,parents=True,exist_ok=True)
os.chmod(str(backup_root),0o700)
backup=Path(tempfile.mkdtemp(prefix='paridad-ventas-',dir=str(backup_root)))
os.chmod(str(backup),0o700)
rows=[]
for i,item in enumerate(actions):
    name='%02d.bak'%i
    target=backup/name
    with target.open('wb') as output: output.write(item['current'])
    os.chmod(str(target),0o600)
    rows.append(dict(path=item['path'],backup=name,mode=item['permission'],
                     original_sha256=digest(item['current']),applied_sha256=digest(item['target'])))
manifest=backup/'manifest.json'
manifest.write_text(json.dumps(rows,indent=2),encoding='utf-8')
os.chmod(str(manifest),0o600)
changed=[]
try:
    for item in actions:
        if item['kind']!='pendiente': continue
        if item['file'].read_bytes()!=item['current']: abort('Edición concurrente: '+item['path'])
        atomic(item['file'],item['target'],item['permission'])
        changed.append(item)
except BaseException:
    for item in reversed(changed):
        if digest(item['file'].read_bytes())==digest(item['target']):
            atomic(item['file'],item['current'],item['permission'])
    raise
print('OK: publicación selectiva. Respaldo:',str(backup))
print('No se tocó SQL, Zadarma, Analista, Marketing ni grabaciones.')
